// Command and reply frames, little-endian.
// Must stay byte-for-byte in sync with messaging/MeoCommandFrame.java and
// MeoReplyFrame.java (meo-3-open-service/docs/mqtt_messaging.md).
module.exports = (function() {
    "use strict";

    var COMMAND_SIZE = 8;
    var REPLY_SIZE = 10;

    return {
        // Fixed, not a counter: the gateway service publishes commands too and
        // its counter restarts at 0, so a counter here would collide with it.
        // Costs us requestId as a discriminator — callers correlate on cap.
        REQUEST_ID: 0xFFFF,

        // u16 requestId | u16 cap | i32 value. value is read only for writes.
        build: function(cap, value) {
            var frame = Buffer.alloc(COMMAND_SIZE);
            frame.writeUInt16LE(this.REQUEST_ID, 0);
            frame.writeUInt16LE(cap, 2);
            frame.writeInt32LE(value, 4);
            return frame;
        },

        // u16 requestId | u8 ok | u16 cap | 4-byte value | u8 error.
        // Value bytes are i32 for a write and f32 for a read, so both readings
        // come back raw; the caller knows which capability it sent.
        parseReply: function(payload) {
            if (!Buffer.isBuffer(payload) || payload.length !== REPLY_SIZE) { return null; }
            return {
                requestId: payload.readUInt16LE(0),
                ok: payload.readUInt8(2) !== 0,
                cap: payload.readUInt16LE(3),
                valueInt: payload.readInt32LE(5),
                valueFloat: payload.readFloatLE(5),
                // MeoCmdErrCode: 1 bad request, 2 unknown cap, 3 handler failed.
                error: payload.readUInt8(9)
            };
        }
    };
}());
